import crypto from 'crypto';

export const hashVerdict = (role) => {
  const timestamp = new Date().toISOString();
  const data = \\::\\;
  return crypto.createHash('sha256').update(data).digest('hex');
};

export function classifyProfile(profile) {
  const { followers, engagementRate, socials } = profile;

  let tier = 1;
  if (followers > 100000) tier = 3;
  else if (followers > 10000) tier = 2;

  let category = 'General';
  if (socials.includes('Instagram') && engagementRate > 0.8) category = 'Fashion';
  else if (socials.includes('TikTok') && engagementRate > 0.7) category = 'Lifestyle';
  else if (socials.includes('LinkedIn')) category = 'Tech';

  return {
    category,
    tier,
    engagementScore: Math.round(engagementRate * 100),
    offers: generateOffers(category, tier)
  };
}

function generateOffers(category, tier) {
  const offers = {
    Fashion: ['StyleHub', 'BrandX'],
    Lifestyle: ['GlowUp', 'VibeReach'],
    Tech: ['GadgetPro', 'InnovateNow'],
    General: ['OpenPromo']
  };
  return offers[category] || [];
}

